from pathlib import Path
import json,html,importlib.util
R=Path(__file__).resolve().parents[1];S=importlib.util.spec_from_file_location('sitebuild',R/'scripts/build-cinematic.py');m=importlib.util.module_from_spec(S);S.loader.exec_module(m);E=html.escape;D=m.D

def save(slug,title,body): (R/(slug+'.html')).write_text(m.document(title,'<main id="main">'+body+'</main>'))
def opening(kicker,title,lead=''):return f'<section class="page-opening" data-tone="light"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lead">{lead}</p></section>'
contact='''<section class="page-opening" data-tone="light"><div class="contact-layout"><div class="contact-intro"><p class="eyebrow">A conversation about your institution</p><h1>Start with<br><em>your school.</em></h1><p>Tell NILKEEPR what your athletic program or district needs. The school team can walk through oversight, implementation, and licensing.</p><div class="portal-note"><p class="eyebrow">Already a school user?</p><a class="text-link" href="https://nilkeepr.net/institutional/signin">Open your school account</a></div></div><form class="contact-panel" id="inquiry"><h2>Prepare your inquiry.</h2><label for="name">Your name</label><input id="name" name="name" autocomplete="name" required><label for="email">Work email</label><input id="email" name="email" type="email" autocomplete="email" required><label for="school">School or district</label><input id="school" name="school" autocomplete="organization" required><label for="interest">I’d like to discuss</label><select id="interest" name="interest"><option>school licensing</option><option>district licensing</option><option>data privacy and consent</option><option>a platform demonstration</option></select><label for="message">What would help your team?</label><textarea id="message" name="message"></textarea><button class="button" type="submit">Open email draft</button><p class="form-note" id="form-status" aria-live="polite">Opens your email app. Review and send the draft there. No information is stored by this page.</p></form></div><div class="contact-direct"><a href="mailto:schools@nilkeepr.net">schools@nilkeepr.net</a><a href="tel:+18774197715">1-877-419-7715</a><a href="mailto:support@nilkeepr.net">General support</a></div></section>''';save('contact','Talk to the school team',contact)
about=opening('About NILKEEPR','One ecosystem.<br><em>Distinct responsibilities.</em>','NILKEEPR connects athletes, agents, brands, schools, and families across the name, image, and likeness landscape.')+'''<section class="inner-content" data-tone="light"><div class="about-split"><img src="assets/athlete-scene.webp" alt="Conceptual athletic opportunity and protection scene"><div><p class="eyebrow">A transparent starting point</p><h2>Talent meets<br><em>opportunity.</em></h2><p>NILKEEPR’s mission is to create a transparent, compliant, and empowering NIL ecosystem. Its stated vision brings athlete development, representation, brand partnerships, institutional oversight, and parental protection into one platform.</p><p>The school-compliance service has a deliberately separate role: disclosure, documentation, and read-only oversight. It does not facilitate or negotiate NIL deals.</p></div></div><div class="audience-list">'''
aud=[('Student-athletes','AlphaMind™ assessment, sport-specific skills evaluation, media and brand analysis, marketplace access, deal management, and performance analytics.','athletes'),('Agents','A three-tier certification pathway: Foundation covers NIL fundamentals; Professional covers negotiation and athlete management; Expert serves experienced representatives. Client portfolios, commission tracking, and compliance tools support the wider agent program.','agents'),('Brand partners','Athlete discovery, campaign management, deal workflow, and performance metrics support brand partnerships in the wider NILKEEPR ecosystem.','brands'),('Schools & districts','Roster management, disclosure tracking, compliance visibility, reports, and exports support institutional oversight.','schools'),('Parents & guardians','Consent and guardian controls provide a defined way to review minor athletes’ activities and information access.','support')]
for title,copy,email in aud:about+=f'<article><h3>{title}</h3><div><p>{copy}</p><a class="text-link" href="mailto:{email}@nilkeepr.net">Contact the {E(title.lower())} team</a></div></article>'
about+='''</div><div class="reading-document"><h2>Wider platform capabilities</h2><p>NILKEEPR describes a marketplace for athlete and brand opportunities; Stripe Connect-powered payments; digital portal agreements with PDF audit trails, SHA-256 verification, and signature capture; and guardian approval and disclosure workflows. These are company-described features of the wider platform, not functions provided by this informational website.</p><p>The company identifies Protected Harbor as its sole technology and hosting vendor. Its published location is Greenwich, Connecticut 06830.</p><a class="text-link" href="contact.html">Discuss the right pathway</a></div></section>''';save('about','About NILKEEPR',about)
platform=opening('School platform / Practical overview','A connected record.<br><em>A defined school role.</em>','Tools for schools to monitor self-reported NIL activity and document oversight without managing the athlete’s deal.')+'''<section class="inner-content" data-tone="light"><div class="reading-layout"><nav class="reading-nav" aria-label="On this page"><a href="#capabilities">School capabilities</a><a href="#safeguards">Safeguards</a><a href="#boundaries">Service boundaries</a><a href="#licensing">Licensing</a></nav><div class="reading-document"><h2 id="capabilities">What the school view brings together</h2>'''
for title,copy in m.tools:platform+=f'<h3>{title}</h3><p>{copy}</p>'
platform+='''<h2 id="safeguards">Documentation with context</h2><p>The company describes immutable, timestamped audit logs, logged school access, encrypted data in transit and at rest, breach-notification protocols, and reports prepared for state associations or court inquiries. These are NILKEEPR’s stated platform features, not independent certifications or guarantees of an eligibility or legal outcome.</p><p>Disclosures originate with student-athletes; consent is required for minors. Schools view relevant information but do not create or maintain the athlete’s education records through this platform.</p><h2 id="boundaries">Oversight without deal involvement</h2><ul><li>No negotiation of NIL deals.</li><li>No approval or denial of opportunities.</li><li>No athlete valuations or NIL commissions.</li><li>No influence on recruiting decisions.</li><li>No replacement for a school’s SIS, gradebook, or eligibility authority.</li></ul><p>The service is intended to support transparency and compliance in the state of operation. Ask the school team about your institution’s specific requirements.</p><h2 id="licensing">Institutional licensing</h2><p>Individual-school licensing includes dashboard access, disclosure monitoring, documentation, and onboarding. District master agreements add a centralized view, bulk reporting, and priority implementation and training. The source describes no per-athlete fees, no usage-based pricing, and no NIL commissions.</p><p>Public pricing is not published. Existing account holders can access their school account; new institutions can request a demonstration and tailored plan details.</p><a class="text-link" href="contact.html">Request a school demonstration</a><h2>Compliance overview document</h2><p>Request the company’s current PDF overview directly from the school team.</p><a class="text-link" href="mailto:schools@nilkeepr.net?subject=Compliance%20overview%20PDF%20request">Request the compliance PDF</a></div></div></section>''';save('platform','School platform overview',platform)
data=opening('Data & consent','Visibility is useful.<br><em>Boundaries are essential.</em>','A parent-consented, student-reported environment with read-only access for schools.')+'''<section class="inner-content" data-tone="light"><div class="reading-layout"><nav class="reading-nav" aria-label="On this page"><a href="#source">Who controls the data</a><a href="#access">What schools see</a><a href="#consent">Consent & safeguards</a></nav><div class="reading-document"><h2 id="source">The student remains the source</h2><p>Student-athletes self-submit academic and NIL disclosures. Parents or guardians provide consent for minors. Schools view compliance-relevant information; they do not input, edit, or control data.</p><h2 id="access">Limited by design</h2><p>The school view includes school name and class year, reported academic eligibility status, NIL disclosure summaries, consent status, disclosure timestamps, and audit history. Exact compensation figures are not displayed.</p><p>Full dates of birth, parent contact information, private communications, financial account details, and non-compliance or marketing data are excluded.</p><h2 id="consent">Child privacy & consent</h2><p>The source requires parent or guardian consent for athletes under 18. Consent is recorded, timestamped, and revocable. Parents can review the information made available to schools.</p><h3>FERPA-aligned architecture</h3><p>NILKEEPR describes voluntary student submissions, access under legitimate educational interest, auditable school access, and an architecture that does not replace or duplicate school education-record systems. It describes its platform as FERPA-aligned and COPPA-compliant. These are company representations, not independent verification of an institution’s legal compliance.</p><h3>Auditability & security</h3><p>NILKEEPR states that school access is logged and timestamped, data is encrypted in transit and at rest, and breach-notification protocols are in place. It also states that school-compliance data is not sold, marketed, or shared externally. A Student Data Privacy Addendum is available on request; review the full privacy policy and contractual terms for their applicable scope and exceptions.</p><a class="text-link" href="mailto:schools@nilkeepr.net?subject=Student%20Data%20Privacy%20Addendum%20request">Request the Data Privacy Addendum</a><h2>Read the full policies</h2><p><a href="privacy.html">Privacy Policy</a> · <a href="terms.html">Terms & Conditions</a> · <a href="communications-consent.html">Communications Consent</a></p></div></div></section>''';save('data-and-consent','Data and consent',data)
trans=(R/'assets/source/school-compliance-transcript.txt').read_text();save('transcript','School compliance video transcript',opening('NILKEEPR / Accessible transcript','The school overview.<br><em>In their words.</em>')+'<section class="inner-content" data-tone="light"><div class="reading-document">'+''.join('<p>'+E(p)+'</p>' for p in trans.split('\n\n') if p.strip())+'<a class="text-link" href="index.html#explainer">Return to the explainer</a></div></section>')
# Preserve actual legal text and heading structure; do not rewrite policy meaning.
for slug in ['privacy','terms','communications-consent','email-policy']:
 route=next(x for x in D['routes'] if x['local_route'].rstrip('/')=='/'+slug)
 text=route['cleaned_text'];heads=route.get('headings',[]);htexts={h.get('text','') if isinstance(h,dict) else str(h) for h in heads};lines=text.splitlines();blocks=[]
 for line in lines:
  line=line.strip()
  if slug=='terms' and line=='Terms and Conditions':continue
  if not line or line in ['California privacy controls','Do Not Sell or Share my Personal Information. This choice also disables optional analytics and marketing sharing.','Opt out of sale/sharing','Back to Home','Contact Privacy Team','Contact Legal Team','Terms of Service•Home','Privacy Policy•Home']:continue
  tag='h2' if line in htexts or (len(line)<100 and line[:1].isdigit() and '. ' in line[:8]) else 'p'
  rendered=E(line)
  if tag=='p':
   policy_links={'Privacy Request Center in your account settings':'https://nilkeepr.net/settings?tab=data','Email Outreach Policy':'email-policy.html','Privacy Policy':'privacy.html','Terms &amp; Conditions':'terms.html','Terms of Service':'terms.html','Communications Consent':'communications-consent.html'}
   for label,destination in policy_links.items():
    if label in rendered and (line not in ['Privacy Policy','Communications Consent'] or slug=='email-policy'):
     rendered=rendered.replace(label,f'<a href="{destination}">{label}</a>')
  blocks.append(f'<{tag}>{rendered}</{tag}>')
 title={'privacy':'Privacy Policy','terms':'Terms & Conditions','communications-consent':'Communications Consent','email-policy':'Email Outreach Policy'}[slug]
 extra='<h2 id="privacy-choices">Your privacy choices</h2><p>To make a privacy, deletion, or do-not-sell/share request, contact the company using the channels in the policy above. This redesign does not install advertising cookies or analytics trackers.</p><a class="text-link" href="mailto:legal@nilkeepr.net?subject=Privacy%20request">Contact privacy support</a>' if slug=='privacy' else ''
 save(slug,title,opening('Policies & information',title)+f'<section class="inner-content" data-tone="light"><div class="reading-layout"><nav class="reading-nav" aria-label="Policies"><a href="privacy.html">Privacy</a><a href="terms.html">Terms</a><a href="communications-consent.html">Communications</a><a href="email-policy.html">Email policy</a></nav><div class="reading-document"><p class="policy-source-note">NILKEEPR’s published policy text, reproduced for reference. This redesign does not operate the company’s accounts or data services.</p>'+('<div class="portal-note"><p>Account privacy preferences and data requests are managed by NILKEEPR. This reference page does not change your account settings.</p><a class="text-link" href="https://nilkeepr.net/settings?tab=data">Account privacy settings</a><br><a class="text-link" href="mailto:legal@nilkeepr.net">Contact the privacy team</a></div>' if slug=='privacy' else '')+''.join(blocks)+extra+'</div></div></section>')
save('404','Page not found',opening('NILKEEPR','A different path<br><em>starts here.</em>','We couldn’t find that page.')+'<section class="inner-content" data-tone="light"><a class="button" href="index.html">Return to school compliance</a></section>')
p404=R/'404.html';p404.write_text(p404.read_text().replace('<head>','<head><base href="https://vastlyresilient.github.io/nilkeepr-redesign/">'))
