for src,dest in {'school-compliance':'index.html','contact':'contact.html','about':'about.html','privacy':'privacy.html','privacy-policy':'privacy.html','terms':'terms.html','communications-consent':'communications-consent.html','email-policy':'email-policy.html','school-admin/pricing':'platform.html#licensing'}.items():
 path=R/src;path.mkdir(parents=True,exist_ok=True);relative='../'*len(src.split('/'))+dest;(path/'index.html').write_text(f'<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="refresh" content="0;url={relative}"><title>NILKEEPR</title><a href="{relative}">Continue to NILKEEPR</a></html>')
